(* [comment removed for export] *)
Definition tc_frame (m : mem) (sp ra s0 s1 s2 s3 s4 s5 : word) (junk : list byte) : Prop :=
  rw_cells rsegs m (bv_unsigned sp + -80) [CB 24 junk; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

Definition TC_SEG_STACK : Z := 80.

(* [comment removed for export] *)
Definition tc_seg1_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (f np vp : Z) (name value : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' junk vp',
    ms' = MS (mkR (Z_to_bv 64 P_TCNE_RET1) (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2
                  (Z_to_bv 64 (zlength name)) (Z_to_bv 64 np) (Z_to_bv 64 (elem_block_size name (trim value))) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 f) (Z_to_bv 64 (zlength (trim value))) s4 (Z_to_bv 64 vp') s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 ROPNEW) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -80)
    /\ tc_frame m' sp ra s0 s1 s2 s3 s4 s5 junk
    /\ bytes_at rsegs m' vp' (trim value)
    /\ ((vp <= vp' /\ vp' + zlength (trim value) <= vp + zlength value) \/ (vp' = 0 /\ trim value = [])).

Definition tc_seg1_stmt : Prop := forall (Fa f np vp ec : Z) (name value : list byte) (lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  bytes_at rsegs m vp value ->
  zlength name <= 65533 -> zlength value <= 65533 -> vp + zlength value < 2^64 ->
  (vp + zlength value <= lo \/ bv_unsigned sp <= vp) ->
  stk rsegs m lo (bv_unsigned sp) -> lo + TC_SEG_STACK <= bv_unsigned sp -> hceil <= lo ->
  mem_inv rsegs m ->
  evt rsegs (tc_seg1_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc f np vp name value lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 Fa) (Z_to_bv 64 f) (Z_to_bv 64 np) (Z_to_bv 64 (zlength name))
              (Z_to_bv 64 vp) (Z_to_bv 64 (zlength value)) (Z_to_bv 64 ec) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_FIELDS_NEW_ELEMENT) fc None m (seg_rom rsegs)).

Lemma tc_seg1 : tc_seg1_stmt.
