Definition TC_SEG2_STACK : Z := 80 + VT_STACK.

(* [comment removed for export] *)
Definition tc_seg2_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (A f np vp' : Z) (name tv : list byte) (junkB : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' pad tail,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (A + 48, A + elem_block_size name tv)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' A [CB 48 (firstn 48 junkB)]
    /\ rw_cells rsegs m' (A + 48) (ValCells (mkElt f name tv pad tail))
    /\ zlength tail = elem_block_size name tv - 60 - zlength name - zlength tv
    /\ bytes_at rsegs m' np name /\ bytes_at rsegs m' vp' tv.

Definition tc_seg2_stmt : Prop := forall (A f np vp' : Z) (name tv : list byte) (lo : Z) (junkF junkB : list byte)
    (ra sp : word) gp tp (t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 s4x : word)
    (F : bvmap 5 word) fc (m : mem),
  tc_frame m sp ra s0 s1 s2 s3 s4 s5 junkF ->
  rw_cells rsegs m A [CB (Z.to_nat (elem_block_size name tv)) junkB] -> rblock_range A (elem_block_size name tv) ->
  bytes_at rsegs m np name -> bytes_at rsegs m vp' tv ->
  zlength name <= 65533 -> zlength tv <= 65533 -> 0 <= f < 2^16 ->
  (np + zlength name <= A \/ A + elem_block_size name tv <= np) -> (vp' + zlength tv <= A \/ A + elem_block_size name tv <= vp') ->
  (np + zlength name <= lo \/ bv_unsigned sp <= np) -> (vp' + zlength tv <= lo \/ bv_unsigned sp <= vp') ->
  stk rsegs m lo (bv_unsigned sp + -80) -> lo + TC_SEG2_STACK <= bv_unsigned sp -> hceil <= lo ->
  mem_inv rsegs m ->
